SourceCode.Declaration:
public class GUPPriceDetailForm extends McrPriceHistoryForm
{
    private AmountCur totalMarginComponentPriceChange;
    private AmountCur baseNetPrice;
    private AmountCur totalEstimatedChargeAmount;
    private Common    caller;
    private Map       estimatedAmountCache;

}

Method.Source:
protected void new(Common _common)
{
    super(_common);
    caller = _common;
    this.calculatePrices();
    this.calculateCharges();
}

protected void calculatePrices()
{
    this.calculateTotalMarginComponentPriceChange();

    //This is the base price without margin adjustment
    baseNetPrice = this.getUnitPriceExtendedAmount() - totalMarginComponentPriceChange;
}

protected void calculateCharges()
{
    estimatedAmountCache = new Map(Types::Int64, Types::Real);

    MarkupTrans markupTrans;
    while select markupTrans
        where markupTrans.TransTableId == caller.tableId
        && markupTrans.TransRecId == caller.RecId
    {
        totalEstimatedChargeAmount += this.calculateEstimateChargeAmount(markupTrans);
    }
}

public static GUPPriceDetailForm construct(Common _common)
{
    return new GUPPriceDetailForm(_common);
}

public void calculateTotalMarginComponentPriceChange()
{
    GUPMarginComponentAdjustmentHistory adjustmentHistory;
    select sum(Amount) from adjustmentHistory
        where adjustmentHistory.InventTransId == this.getInventTransId();

    totalMarginComponentPriceChange = adjustmentHistory.Amount * this.getQty();
}

public AmountCur displayBaseNetPrice(MCRPriceHistory _priceHistory)
{
    return baseNetPrice;
}

public AmountCur displayBaseUnitPrice(MCRPriceHistory _priceHistory)
{
    return baseNetPrice / (this.getQty() == 0 ? 1 : this.getQty());
}

public AmountCur displayTotalMarginComponentPriceChange()
{
    return totalMarginComponentPriceChange;
}

public AmountCur displayMarginComponentNetPriceChange(GUPMarginComponentAdjustmentHistory _adjustmentHistory)
{
    return this.getQty() * _adjustmentHistory.Amount;
}

public AmountCur displayMarginComponentUnitPriceChange(GUPMarginComponentAdjustmentHistory _adjustmentHistory)
{
    return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
        this.getItemId(),
        this.getInventDim().inventDimId,
        _adjustmentHistory.Amount,
        _adjustmentHistory.UnitId,
        this.getUnitId());
}

public RetailDiscountOfferLineDiscountMethod displayDiscountMethod(RetailSalesQuotationDiscountLineView _discountLine)
{
    if (_discountLine.Percentage != 0)
    {
        return RetailDiscountOfferLineDiscMethodBase::PercentOff;
    }

    if (_discountLine.DealPrice != 0)
    {
        return RetailDiscountOfferLineDiscMethodBase::Price;
    }

    return RetailDiscountOfferLineDiscMethodBase::AmountOff;
}

public real displayDiscountValue(RetailSalesQuotationDiscountLineView _discountLine)
{
    return _discountLine.DiscountAmount ? _discountLine.DiscountAmount : _discountLine.Percentage;
}

public AmountCur displayNetDiscountAmount(RetailSalesQuotationDiscountLineView _discountLine)
{
    return _discountLine.Amount * -1;
}

public AmountCur displayUnitDiscountAmount(RetailSalesQuotationDiscountLineView _discountLine)
{
    return (_discountLine.Amount / this.getQty()) * -1;
}

public GUPPriceComponentCodeName displayDiscountPriceComponentCode(RetailSalesQuotationDiscountLineView _discountLine)
{
    RetailPeriodicDiscount  discount;
    select firstonly PriceComponentCodeName from discount
            where discount.OfferId == _discountLine.PeriodicDiscountOfferId;

    return discount.PriceComponentCodeName;
}

public PriceUnit displayPriceUnit(MCRPriceHistory _mcrPriceHistory)
{
    PriceUnit priceUnitLocal;
    // Price unit only applicable for price (not discount)
    if (_mcrPriceHistory.PriceHistoryType == MCRPriceHistoryType::TradePrice)
    {
        priceUnitLocal = _mcrPriceHistory.priceUnit();
    }
    return priceUnitLocal;
}

public container dislayUnitConversionImageForBasePrice(MCRPriceHistory _priceHistory)
{
    if (_priceHistory.UnitId != this.getUnitId())
    {
        ImageReference  imageReference = ImageReference::constructForSymbol(ImageReferenceSymbol::Sort, "@GlobalUnifiedPricing:GUPPriceDetailUnitConversionMessage");
        return imageReference.pack();
    }

    return conNull();
}

public container dislayUnitConversionImageForMarginComponent(GUPMarginComponentAdjustmentHistory _adjustmentHistory)
{
    if (_adjustmentHistory.UnitId != this.getUnitId())
    {
        ImageReference  imageReference = ImageReference::constructForSymbol(ImageReferenceSymbol::Sort, "@GlobalUnifiedPricing:GUPPriceDetailUnitConversionMessage");
        return imageReference.pack();
    }
    return conNull();
}

private AmountCur calculateEstimateChargeAmount(MarkupTrans _markupTrans)
{
    AmountCur chargeAmount;
    if (!estimatedAmountCache.exists(_markupTrans.RecId))
    {
        // Reuse persisted calculated charge amount instead of recalculating
        if (_markupTrans.CalculatedAmount != 0)
        {
            chargeAmount = _markupTrans.getCalculatedAmountRepresentable();
            estimatedAmountCache.insert(_markupTrans.RecId, chargeAmount);
            return chargeAmount;
        }

        if (caller.tableId == tableNum(salesLine))
        {
            SalesLine salesLine = caller as salesLine;

            chargeAmount = Markup::calcMarkupAmount(_markupTrans,
                                                       salesLine.SalesQty,
                                                       salesLine.lineAmountExclTax(),
                                                       0,
                                                       salesLine.inclTax(),
                                                       NoYes::No,
                                                       _markupTrans.CurrencyCode,
                                                       _markupTrans.TransDate,
                                                       0,
                                                       0,
                                                       null,
                                                       false,
                                                       0,
                                                       '',
                                                       false,
                                                       false);
            estimatedAmountCache.insert(_markupTrans.RecId, chargeAmount);
        }
    }
    else
    {
        chargeAmount = estimatedAmountCache.lookup(_markupTrans.RecId);
    }
    return  chargeAmount;
}

public AmountCur getTotalEstimatedChargeAmount()
{
    return totalEstimatedChargeAmount;
}

public AmountCur displayEstimatedChargeAmount(MarkupTrans _markupTrans)
{
    return estimatedAmountCache.lookup(_markupTrans.RecId);
}
